  rw [pow_two, Nat.prime_two.dvd_mul] at h;
  cases h <;> assumption

theorem even_of_even_sqr {m : ℕ} (h : 2 ∣ m ^ 2) : 2 ∣ m    := by
  rw [pow_two, Nat.prime_two.dvd_mul] at h
  exact Or.inl h.apply }

theorem t1 {m n : ℕ} (coprime_mn : m.Coprime n) : m ^ 2 ≠ 2 * n ^ 2   := by
  intro sqr_eq
  have : 2 ∣ m := even_of_even_sqr (by rw [sqr_eq]; exact mul_left_mem_mul_right m n _ 1);

